/* `reg` restricts a leg to what the Bayern-Ticket and the Deutschland-Ticket
   buy. Without it the router hands back an IC or a Railjet that saves twenty
   minutes and costs forty euros nobody budgeted for. */
const REG = ["REGIONAL_RAIL", "REGIONAL_FAST_RAIL", "METRO", "SUBWAY", "TRAM", "BUS"];
const T = (dep, arr, to, via, x, bus, reg) => ({ M: bus ? "Bus" : "Train", dep, arr, to, via, x, only: reg ? REG : null });
/* A train that is already paid for, or a fixed airport shuttle. The planner
   does not get to pick these: the times are printed on a ticket. */
const B = (dep, arr, to, via, line, x, bus) => ({ M: bus ? "Bus" : "Train", dep, arr, to, via, x, book: line });

